<template><Card class="logs-list-card"><div class="header-row"><h3>Recent logs</h3><span>{{ logs.length }} logs</span></div><ul v-if="logs.length" class="log-items"><li v-for="log in logs" :key="log.id"><div><strong>{{ log.title ?? log.id }}</strong><div class="details">{{ log.map ?? 'Unknown map' }} • {{ date(log.timestamp) }}</div><div class="performance">{{ log.kills ?? 0 }} K · {{ log.deaths ?? 0 }} D · {{ number(log.damage) }} dmg</div></div><NuxtLink class="log-link" :to="`/log/${log.id}`" :aria-label="`Open log ${log.id}`">Open log →</NuxtLink></li></ul><p v-else class="empty-logs">No public logs were available for this player.</p></Card></template>
<script setup lang="ts">import type { PlayerLogReference } from '~~/features/player/types'; defineProps<{ logs: PlayerLogReference[] }>(); const date=(value?:string)=>value?new Date(value).toLocaleDateString():'Date unavailable'; const number=(value?:number)=>new Intl.NumberFormat('en-US').format(value??0)</script>
